import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        new Main().start();
    }

    private void start() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int n = in.readInt();
        int k = in.readInt();
        int[] basePoly = new int[10];
        for (int i = 0; i < k; i++) {
            basePoly[in.readInt()] = 1;
        }

        int[] result = new int[]{1};
        int exp = n / 2;

        while (true) {
            if ((exp & 1) == 1) {
                result = multiplyPolynomials(result, basePoly, MOD);
            }
            exp >>>= 1;
            if (exp == 0) break;
            basePoly = multiplyPolynomials(basePoly, basePoly, MOD);
        }

        long answer = 0;
        for (int coef : result) {
            answer = (answer + (long) coef * coef) % MOD;
        }
        out.printLine(answer);
        out.close();
    }

    private int[] multiplyPolynomials(int[] p1, int[] p2, int mod) {
        int requiredLength = p1.length + p2.length - 1;
        int fftSize = 1;
        while (fftSize < requiredLength) fftSize <<= 1;

        double[] pr1 = new double[fftSize];
        double[] pi1 = new double[fftSize];
        double[] pr2 = new double[fftSize];
        double[] pi2 = new double[fftSize];

        for (int i = 0; i < p1.length; i++) {
            long val = p1[i] % mod;
            if (val < 0) val += mod;
            pr1[i] = val & 0x7fffL;
            pi1[i] = val >>> 15;
        }

        for (int i = 0; i < p2.length; i++) {
            long val = p2[i] % mod;
            if (val < 0) val += mod;
            pr2[i] = val & 0x7fffL;
            pi2[i] = val >>> 15;
        }

        performFFT(pr1, pi1, false);
        performFFT(pr2, pi2, false);

        double[] resRe = new double[fftSize];
        double[] resIm = new double[fftSize];

        for (int i = 0; i < fftSize; i++) {
            int j = (fftSize - i) & (fftSize - 1);
            double a1r = (pr1[i] + pr1[j]) * 0.5;
            double a1i = (pi1[i] - pi1[j]) * 0.5;
            double a2r = (pi1[i] + pi1[j]) * 0.5;
            double a2i = (pr1[j] - pr1[i]) * 0.5;

            double b1r = (pr2[i] + pr2[j]) * 0.5;
            double b1i = (pi2[i] - pi2[j]) * 0.5;
            double b2r = (pi2[i] + pi2[j]) * 0.5;
            double b2i = (pr2[j] - pr2[i]) * 0.5;

            resRe[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resIm[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        }

        performFFT(resRe, resIm, true);

        int[] result = new int[requiredLength];
        for (int i = 0; i < requiredLength; i++) {
            long realPart = Math.round(resRe[i]);
            long imagPart = Math.round(resIm[i]);
            long combined = (realPart + (imagPart << 15)) % mod;
            result[i] = (int) combined;
        }
        return result;
    }

    private void performFFT(double[] real, double[] imag, boolean inverse) {
        int n = real.length;
        int logN = 31 - Integer.numberOfLeadingZeros(n - 1);
        for (int i = 1; i < n; i++) {
            int rev = Integer.reverse(i) >>> (32 - logN);
            if (i < rev) {
                double temp = real[i];
                real[i] = real[rev];
                real[rev] = temp;
                temp = imag[i];
                imag[i] = imag[rev];
                imag[rev] = temp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            double cosStep = Math.cos(angle);
            double sinStep = Math.sin(angle);

            for (int i = 0; i < n; i += len) {
                double cos = 1.0;
                double sin = 0.0;

                for (int j = 0; j < half; j++) {
                    double uReal = real[i + j];
                    double uImag = imag[i + j];
                    double vReal = real[i + j + half] * cos - imag[i + j + half] * sin;
                    double vImag = real[i + j + half] * sin + imag[i + j + half] * cos;

                    real[i + j] = uReal + vReal;
                    imag[i + j] = uImag + vImag;
                    real[i + j + half] = uReal - vReal;
                    imag[i + j + half] = uImag - vImag;

                    double newCos = cos * cosStep - sin * sinStep;
                    sin = cos * sinStep + sin * cosStep;
                    cos = newCos;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                real[i] /= n;
                imag[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar, numChars;

        public InputReader(InputStream stream) { this.stream = stream; }

        private int read() {
            if (numChars == -1) throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try { numChars = stream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int readInt() {
            int c = read();
            while (c <= 32) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new NumberFormatException();
                res = res * 10 + c - '0';
                c = read();
            } while (c > 32);
            return res * sgn;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) { writer = new PrintWriter(stream); }

        public void printLine(Object obj) { writer.println(obj); }

        public void close() { writer.close(); }
    }
}
